import json, math

with open('/home/USER/runs/paper/qwen-h0c1-card/frozen/held-out-reference-3/play/users/u098/system/state/workspace/grids.json', 'r') as f:
    grids_str = json.load(f)

demo_in = [[int(cell) for cell in row] for row in grids_str['Demo pair 1 input']]
demo_out = [[int(cell) for cell in row] for row in grids_str['Demo pair 1 output']]

# For each row r, what columns c get cleared?
zeros_per_row = {}
for r in range(20):
    for c in range(20):
        if demo_out[r][c] == 0:
            zeros_per_row.setdefault(r, []).append(c)

print("Output zero columns per row:")
for r in sorted(zeros_per_row.keys()):
    print(f"  Row {r}: {zeros_per_row[r]}")

center_r, center_c = 6.5, 8.5

print("\nDistance from center (6.5, 8.5):")
for r in [0, 1, 6, 7, 10, 12, 13]:
    for c in zeros_per_row.get(r, []):
        dr = r - center_r
        dc = c - center_c
        dist = (dr**2 + dc**2)**0.5
        print(f"  ({r}, {c}): dr={dr:.2f}, dc={dc:.2f}, dist={dist:.2f}")

# Check the test input's zero positions
test_in = [[int(cell) for cell in row] for row in grids_str['Test input']]

def get_zero_positions(grid):
    pos = set()
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 0:
                pos.add((r, c))
    return sorted(pos)

print("Test input zero positions:", get_zero_positions(test_in))

